def parse_demo(text, marker):
    start = text.index(marker)
    tail = text[start:].splitlines()[1:23]
    return [[int(x) for x in line.split()] for line in tail]

def extract_tiles(g):
    h,w=len(g),len(g[0]); tiles=[]
    for r in range(h-4):
      for c in range(w-4):
        inner={g[i][j] for i in range(r+1,r+4) for j in range(c+1,c+4)}
        if len(inner)!=1: continue
        fill=next(iter(inner))
        # frame is perimeter uniform color, different fill
        border={g[i][j] for i in range(r,r+5) for j in range(c,c+5) if i in (r,r+4) or j in (c,c+4)}
        if len(border)==1 and fill not in border:
          b=next(iter(border))
          tiles.append((r,c,b,fill))
    return sorted(set(tiles))

